<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import AppLayout from '../layouts/AppLayout.vue'
import { studio } from '../api/studio'
import { createLocalVision, calibrationTargets } from '../composables/localVision'
const busy = ref(false), error = ref(''), workspaces = ref([]), sources = ref([]), history = ref([])
const workspaceId = ref(''), session = ref(null), report = ref(null), tab = ref('prepare')
const workspace = ref({name:'', company_name:'',target_role:''})
const source = ref({category:'RESUME',title:'',text:''}), sourceIds = ref([])
const settings = ref({interview_type:'COMPREHENSIVE',difficulty:'INTERMEDIATE',duration_minutes:20,feedback_mode:'COACHING',input_mode:'AUDIO_VIDEO'})
const answer = ref(''), video = ref(null), deviceMessage = ref('장치 확인 버튼을 눌러 카메라와 마이크를 연결하세요.'), deviceReady = ref(false)
let disposed=false
let stream, timer, recorder, capture, uploads = Promise.resolve(), captureSeq = -1, uploadError
const questionReadyMessage=ref('질문을 다 읽었다면 질문 확인 버튼을 누르세요. 누르지 않으면 응답 지연은 미측정입니다.')
const preflightMessage=ref('마이크 품질 검사를 누르고 평소 답변 크기로 말하세요.')
const enrollmentMessage=ref('본인 음성 등록은 선택사항입니다. 등록하지 않은 화자 구분은 미측정입니다.')
let preparedSessionSignature=null,enrollmentRecorder,enrollmentTimer
const recording = ref(false), visionMessage=ref('시선·동작은 카메라 기준 보정 후 관찰합니다.')
const calibrationDialog=ref(null)
let calibrationPreviousFocus
const calibrationIndex=ref(-1)
const calibrationTarget=computed(()=>calibrationTargets[calibrationIndex.value])
let vision, visionTimer, reportTimer, reportGeneration=0
let pendingCapture = null, submissionId = null, submittedText = null, expiryPending = false, stateGeneration = 0
const transcripts=ref([]), transcriptSessionId=ref(null)
const archiveRevision=ref(0),viewingArchive=ref(false),replayUrl=ref('')
const replayCaptureIds=computed(()=>[...new Set(transcripts.value.flatMap(t=>t.capture_refs??[]))])
let captureTimelineKey=null,captureTimelineMs=0
const fileInput=ref(null), editingSource=ref(null)
const remaining = ref(0)
const clock = computed(() => `${Math.floor(remaining.value / 60).toString().padStart(2,'0')}:${Math.floor(remaining.value % 60).toString().padStart(2,'0')}`)
const categories = {RESUME:'이력서',PORTFOLIO:'포트폴리오',COMPANY_INFO:'기업 정보',JOB_DESCRIPTION:'채용 공고'}
watch(()=>settings.value.input_mode,()=>{release();deviceMessage.value='입력 방식이 바뀌었습니다. 장치를 다시 연결하세요.'})
watch(video, element=>{if(element&&stream){element.srcObject=stream;element.play?.()?.catch?.(()=>{})}})
const metricLabels={speech_rate:'말하기 속도',gaze:'보정한 카메라 방향·화면 시선 추정',gesture:'어깨 너비 대비 손목 움직임',pronunciation:'발음 · 음향 관찰',speaker_separation:'본인 음성·배경 화자 구분',content:'답변 내용'}
function formatMetric(value){return typeof value==='number'&&Number.isFinite(value)?value.toFixed(2).replace(/\.?0+$/,''):'미측정'}
async function run(fn) { if(busy.value)return; busy.value=true; error.value=''; try {return await fn()} catch(e){if(disposed)return;error.value=e.response?.data?.detail || e.message || '처리하지 못했습니다. 다시 시도하세요.'} finally {if(!disposed)busy.value=false} }
async function load(){await run(async()=>{workspaces.value=await studio.workspaces();history.value=await studio.sessions()})}
async function selectWorkspace(){editingSource.value=null;source.value={category:'RESUME',title:'',text:''};sourceIds.value=[];sources.value=[];if(workspaceId.value)await run(async()=>{sources.value=await studio.sources(workspaceId.value)})}
async function createWorkspace(){await run(async()=>{const item=await studio.workspace(workspace.value);workspaces.value.push(item);workspaceId.value=item.id;sources.value=[];sourceIds.value=[]})}
async function saveSource(){await run(async()=>{const item=editingSource.value?await studio.revise(workspaceId.value,editingSource.value,source.value):await studio.source(workspaceId.value,source.value);sources.value=await studio.sources(workspaceId.value);sourceIds.value=sourceIds.value.filter(id=>sources.value.some(s=>s.id===id));sourceIds.value.push(item.id);editingSource.value=null;source.value={category:'RESUME',title:'',text:''}})}
async function removeSource(item){await run(async()=>{await studio.removeSource(workspaceId.value,item.id);sources.value=sources.value.filter(s=>s.id!==item.id);sourceIds.value=sourceIds.value.filter(id=>id!==item.id)})}
function editSource(item){if(busy.value)return;editingSource.value=item.id;source.value={category:item.category,title:item.title,text:item.text}}
async function uploadSource(){await run(async()=>{const file=fileInput.value?.files?.[0];if(!file)throw new Error('파일을 선택하세요.');const body=new FormData();body.append('category',source.value.category);body.append('title',source.value.title||file.name);body.append('file',file);const item=await studio.upload(workspaceId.value,body);sources.value=await studio.sources(workspaceId.value);sourceIds.value.push(item.id);fileInput.value.value=''})}
async function calibrateVision(){await run(async()=>{if(!deviceReady.value)throw new Error('먼저 장치를 연결하세요.');visionMessage.value='로컬 영상 모델을 준비하고 있습니다…';if(!vision){const acquired=await createLocalVision();if(disposed){acquired.close();return}vision=acquired}if(disposed)return;vision.resetCalibration();calibrationPreviousFocus=document.activeElement;calibrationIndex.value=0;await nextTick();calibrationDialog.value?.focus();visionMessage.value='화면 5개 지점과 카메라 렌즈를 차례로 바라보세요.'})}
async function captureCalibration(){await run(async()=>{if(calibrationIndex.value<0)return;await vision.calibratePoint(video.value,calibrationIndex.value);if(disposed)return;if(calibrationIndex.value===5){calibrationIndex.value=-1;calibrationPreviousFocus?.focus();visionMessage.value='6지점 눈동자·머리 회전 보정 완료 · 카메라 방향/화면 영역을 추정합니다. 자세가 바뀌면 재보정하세요.'}else calibrationIndex.value++})}
function calibrationKeyboard(event){if(event.key==='Escape'&&!busy.value){event.preventDefault();cancelCalibration()}if(event.key==='Tab'){const nodes=[...(calibrationDialog.value?.querySelectorAll('button:not(:disabled)')??[])];if(!nodes.length){event.preventDefault();return}const i=nodes.indexOf(document.activeElement);if(event.shiftKey&&i<=0){event.preventDefault();nodes.at(-1).focus()}else if(!event.shiftKey&&(i===nodes.length-1||i<0)){event.preventDefault();nodes[0].focus()}}}
function cancelCalibration(){vision?.resetCalibration();calibrationPreviousFocus?.focus();calibrationIndex.value=-1;visionMessage.value='보정을 취소하여 시선은 미측정입니다.'}

function release(){calibrationIndex.value=-1;clearInterval(visionTimer);vision?.close();vision=null;if(recorder?.state==='recording')recorder.stop();recording.value=false;stream?.getTracks().forEach(t=>t.stop());stream=null;deviceReady.value=false}
async function connectDevices(){await run(async()=>{if(settings.value.input_mode==='TEXT')throw new Error('텍스트 면접은 장치를 사용하지 않습니다.');release();if(!navigator.mediaDevices?.getUserMedia)throw new Error('이 브라우저에서는 장치 연결을 지원하지 않습니다. HTTPS 또는 localhost에서 열어주세요.');const acquired=await navigator.mediaDevices.getUserMedia({video:settings.value.input_mode==='AUDIO_VIDEO',audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});if(disposed){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;await nextTick();if(disposed){release();return}if(video.value)video.value.srcObject=stream;deviceReady.value=true;const actual=stream.getAudioTracks()[0]?.getSettings();deviceMessage.value=`장치 연결 완료 · 소음 억제 ${actual?.noiseSuppression?'사용 중':'지원 확인 불가'}`;stream.getTracks().forEach(t=>t.onended=()=>{deviceReady.value=false;deviceMessage.value='장치 연결이 끊겼습니다. 다시 연결하거나 텍스트로 진행하세요.'})})}
async function questionReady(){await run(async()=>{await studio.questionReady(session.value.id);questionReadyMessage.value='질문 확인 완료 · 응답 준비 시간을 관찰합니다.'})}
async function checkMicrophone(){await run(async()=>{if(!stream||!deviceReady.value)throw new Error('먼저 장치를 연결하세요.');const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw new Error('이 브라우저는 마이크 품질 검사를 지원하지 않습니다.');const context=new Context();let input;try{await context.resume();input=context.createMediaStreamSource(stream);const analyser=context.createAnalyser();analyser.fftSize=2048;input.connect(analyser);const samples=new Float32Array(analyser.fftSize);let energy=0,clipped=0,count=0;for(let i=0;i<25&&!disposed;i++){analyser.getFloatTimeDomainData(samples);for(const value of samples){energy+=value*value;if(Math.abs(value)>=.99)clipped++;count++}await new Promise(resolve=>setTimeout(resolve,40))}if(disposed)return;const rms=count?Math.sqrt(energy/count):0,ratio=count?clipped/count:0;preflightMessage.value=`마이크 RMS ${rms.toFixed(3)} · 클리핑 ${(ratio*100).toFixed(2)}% · ${rms<.005?'음량이 작습니다. 마이크 거리와 권한을 확인하세요.':ratio>.01?'입력이 과합니다. 마이크 게인을 낮추세요.':'음량 관찰 완료. 배경 화자 유무는 본인 음성 등록 후 분석합니다.'}`}finally{input?.disconnect();await context.close()}})}
async function enrollSpeaker(){await run(async()=>{if(!deviceReady.value||!stream)throw new Error('마이크 장치를 먼저 연결하세요.');if(!workspaceId.value)throw new Error('지원 준비 묶음을 선택하세요.');if(!window.MediaRecorder)throw new Error('이 브라우저는 음성 등록을 지원하지 않습니다.');if(['ACTIVE','PAUSED','FINALIZING'].includes(session.value?.status))throw new Error('진행 중인 면접을 먼저 종료하세요.');const signature=JSON.stringify({...settings.value,workspace_id:workspaceId.value,source_ids:sourceIds.value});if(session.value?.status!=='READY'||preparedSessionSignature!==signature){session.value=await studio.create({...settings.value,workspace_id:workspaceId.value,source_ids:sourceIds.value});preparedSessionSignature=signature}const localRecorder=enrollmentRecorder=new MediaRecorder(new MediaStream(stream.getAudioTracks())),parts=[];enrollmentMessage.value='8초 동안 주변 사람 없이 혼자 자연스럽게 말하세요. 예: 저는 지원한 직무에 필요한 경험을 설명하겠습니다.';const blob=await new Promise((resolve,reject)=>{localRecorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};localRecorder.onerror=()=>reject(new Error('등록 음성을 녹음하지 못했습니다.'));localRecorder.onstop=()=>{clearTimeout(enrollmentTimer);enrollmentRecorder=null;resolve(new Blob(parts,{type:localRecorder.mimeType||'audio/webm'}))};localRecorder.start();enrollmentTimer=setTimeout(()=>{if(localRecorder.state==='recording')localRecorder.stop()},8000)});if(disposed)return;const body=new FormData();body.append('consent','true');body.append('file',blob,'enrollment.webm');const value=await studio.enrollSpeaker(session.value.id,body);enrollmentMessage.value=value.status==='enrolled'?'본인 음성 등록 완료 · 이 면접에서만 화자 구분에 사용합니다. 설정을 변경하면 다시 등록하세요.':'음성 등록을 제공할 수 없습니다. 해당 항목은 미측정입니다.'})}
function applySession(value){const timelineKey=`${value.id}:${value.turn_index??0}`;if(captureTimelineKey!==timelineKey){captureTimelineKey=timelineKey;captureTimelineMs=0;questionReadyMessage.value='질문을 다 읽었다면 질문 확인 버튼을 누르세요.'}if(session.value?.id!==value.id){transcripts.value=[];transcriptSessionId.value=null}if(session.value?.id===value.id && (value.control_version??0)<(session.value.control_version??0))return;stateGeneration++;session.value=value;remaining.value=value.remaining_seconds??settings.value.duration_minutes*60}
async function start(){await run(async()=>{if(pendingCapture||['ACTIVE','PAUSED','FINALIZING'].includes(session.value?.status))throw new Error('진행 중인 면접을 먼저 종료하세요.');if(settings.value.input_mode!=='TEXT'&&!deviceReady.value)throw new Error('먼저 장치를 확인하거나 텍스트 입력을 선택하세요.');const signature=JSON.stringify({...settings.value,workspace_id:workspaceId.value,source_ids:sourceIds.value});const item=session.value?.status==='READY'&&preparedSessionSignature===signature?session.value:await studio.create({...settings.value,workspace_id:workspaceId.value,source_ids:sourceIds.value});applySession(await studio.control(item.id,'start',{expected_control_version:item.control_version}));tab.value='interview';await nextTick();if(video.value&&stream)video.value.srcObject=stream})}
async function control(action){await run(async()=>{await stopRecording(false);applySession(await studio.control(session.value.id,action,{expected_control_version:session.value.control_version}))})}
async function submitAnswer(){await run(async()=>{await stopRecording(true);const value=await studio.answer(session.value.id,{text:submittedText ?? (submittedText=answer.value),client_submission_id:submissionId || (submissionId=crypto.randomUUID())});applySession(value);answer.value='';submissionId=null;submittedText=null})}
async function retryAnswer(){await run(async()=>{await stopRecording(true);captureTimelineMs=0;applySession(await studio.retryAnswer(session.value.id));transcripts.value=[];transcriptSessionId.value=null;answer.value='';submissionId=null;submittedText=null})}
async function beginRecording(){await run(async()=>{if(pendingCapture)await stopRecording(false);if(settings.value.input_mode==='TEXT')throw new Error('텍스트 면접은 녹음하지 않습니다.');if(!stream||!deviceReady.value)throw new Error('장치를 먼저 연결하세요.');if(!window.MediaRecorder)throw new Error('이 브라우저는 녹음을 지원하지 않습니다. 텍스트로 답변하세요.');const current=await studio.capture(session.value.id,{turn_offset_ms:captureTimelineMs});const chunks=[];const started=performance.now();let lastEnd=0;pendingCapture={...current,turn_offset_ms:captureTimelineMs,calibration:vision?.getCalibration(),featureBatchId:crypto.randomUUID(),chunks,features:[],stopped:false,queue:Promise.resolve()};const pending=pendingCapture;recorder=new MediaRecorder(new MediaStream(stream.getAudioTracks()));recorder.ondataavailable=e=>{if(!e.data.size)return;const end=Math.max(lastEnd,Math.round(performance.now()-started));const item={blob:e.data,startMs:lastEnd,endMs:end};chunks.push(item);lastEnd=end;pending.queue=pending.queue.then(()=>uploadPending(pending)).catch(()=>{});if(chunks.filter(c=>c.blob).reduce((n,c)=>n+c.blob.size,0)>16*1024*1024){recorder.stop();recording.value=false;pending.stopped=true;error.value='연결이 지연되어 녹음을 중단했습니다. 음성 업로드를 다시 시도하세요.'}};recorder.start(1000);recording.value=true;clearInterval(visionTimer);if(vision)visionTimer=setInterval(()=>{if(pending.features.length>=6000)return;try{pending.features.push(vision.sample(video.value,Math.max(0,Math.round(performance.now()-started))))}catch{visionMessage.value='영상 관찰을 이어갈 수 없어 해당 구간은 미측정입니다.';clearInterval(visionTimer)}},200)})}
async function uploadPending(pending){for(let seq=0;seq<pending.chunks.length;seq++){const item=pending.chunks[seq];if(item.uploaded)continue;for(let attempt=0;attempt<3;attempt++){try{await studio.chunk(pending.id,'audio',seq,item.blob,{generation:pending.generation,startMs:item.startMs,endMs:item.endMs});item.uploaded=true;item.blob=null;break}catch(e){if(attempt===2)throw e}}}}
async function stopRecording(final=true){if(!pendingCapture)return;const pending=pendingCapture;clearInterval(visionTimer);if(recording.value){await new Promise(resolve=>{recorder.onstop=resolve;recorder.stop()});recording.value=false;pending.stopped=true}await pending.queue;await uploadPending(pending);if(pending.features.length&&!pending.featuresUploaded){await studio.features(pending.id,{schema_version:'iris-calibrated-v2',generation:pending.generation,batch_id:pending.featureBatchId,calibration:pending.calibration??{method:'binocular_iris_headpose_affine',unit:'calibrated_screen_distance',calibrated:false,point_count:0,validation_error:null},samples:pending.features});pending.featuresUploaded=true}await studio.seal(pending.id,{last_seq:{audio:pending.chunks.length-1},is_final_for_turn:final});captureTimelineMs=pending.turn_offset_ms+(pending.chunks.at(-1)?.endMs??0);pendingCapture=null}
async function endRecording(){await run(()=>stopRecording(true))}
async function finish(){await run(async()=>{await stopRecording(true);applySession(await studio.control(session.value.id,'finish',{expected_control_version:session.value.control_version}));report.value=await studio.report(session.value.id);tab.value='report';trackReport(session.value.id);release();history.value=await studio.sessions()})}
async function loadTranscripts(id=session.value?.id){await run(async()=>{transcriptSessionId.value=id;transcripts.value=await studio.transcripts(id)})}
async function confirmTranscript(item){await run(async()=>{const context=tab.value==='report'?report.value?.session_id:session.value?.id;if(!context||context!==transcriptSessionId.value)throw new Error('현재 면접의 전사를 다시 불러오세요.');const revised=await studio.transcript(transcriptSessionId.value,{turn_index:item.turn_index,text:item.text});await studio.confirmTranscript(transcriptSessionId.value,item.turn_index,revised.revision);transcripts.value=await studio.transcripts(transcriptSessionId.value)})}
function trackReport(id){clearTimeout(reportTimer);const generation=++reportGeneration;let attempts=0;const poll=async()=>{if(generation!==reportGeneration||attempts++>=60)return;try{const value=await studio.report(id);if(generation!==reportGeneration)return;report.value=value;if(value.status==='complete'||value.status==='completed')return}catch{}reportTimer=setTimeout(poll,2000)};reportTimer=setTimeout(poll,2000)}
function clearReplay(){if(replayUrl.value)URL.revokeObjectURL(replayUrl.value);replayUrl.value=''}
async function replayCapture(id){await run(async()=>{clearReplay();const blob=await studio.audioBlob(id);if(disposed)return;replayUrl.value=URL.createObjectURL(blob)})}
async function openArchive(){await run(async()=>{clearTimeout(reportTimer);reportGeneration++;clearReplay();report.value=await studio.archive(report.value.session_id,archiveRevision.value);viewingArchive.value=true})}
async function refreshReport(){if(report.value?.session_id)await openReport(report.value.session_id)}
async function openReport(id){viewingArchive.value=false;clearReplay();transcripts.value=[];transcriptSessionId.value=null;await run(async()=>{report.value=await studio.report(id);archiveRevision.value=report.value.revision??0;tab.value='report';trackReport(id)})}
onMounted(()=>{load();let ticks=0;timer=setInterval(()=>{if(session.value?.status==='ACTIVE'&&session.value?.timer_phase!=='ANALYZING'&&remaining.value>0){remaining.value--;if(remaining.value===0&&!expiryPending&&!busy.value){expiryPending=true;finish().finally(()=>{expiryPending=false})}}if(session.value?.status==='ACTIVE'&&remaining.value===0&&!expiryPending&&!busy.value){expiryPending=true;finish().finally(()=>{expiryPending=false})}if(session.value&&++ticks%5===0&&!busy.value){const id=session.value.id,generation=stateGeneration;studio.session(id).then(value=>{if(generation===stateGeneration&&session.value?.id===id&&!busy.value)applySession(value)}).catch(()=>{});}},1000)})
onBeforeUnmount(()=>{disposed=true;clearReplay();clearTimeout(enrollmentTimer);if(enrollmentRecorder?.state==='recording')enrollmentRecorder.stop();clearInterval(timer);clearTimeout(reportTimer);reportGeneration++;const drain=stopRecording(false);stream?.getTracks().forEach(t=>t.stop());stream=null;clearInterval(visionTimer);vision?.close();vision=null;drain.catch(()=>{})})
</script>
<template>
<AppLayout title="AI 면접 스튜디오" eyebrow="CAREERFIT × AI CORE">
  <div class="studio-tabs" role="navigation" aria-label="면접 단계"><button v-for="[key,label] in [['prepare','면접 준비'],['interview','면접 진행'],['report','결과 리포트'],['history','연습 기록']]" :key="key" :class="{selected:tab===key}" @click="tab=key">{{label}}</button></div>
  <p v-if="error" class="studio-error" role="alert">{{error}}</p><p v-if="busy" role="status">처리 중입니다…</p>
  <template v-if="tab==='prepare'">
    <div class="studio-banner"><span>YOUR NEXT OPPORTUNITY</span><h2>나의 경험으로 준비하는<br/>다음 면접</h2><p>지원 자료를 선택하고 나에게 맞는 면접을 시작하세요.</p></div>
    <div class="studio-grid"><section class="studio-card"><h2>01 지원 준비자료</h2>
      <label>지원 준비 묶음<select :disabled="busy" v-model="workspaceId" @change="selectWorkspace"><option value="">새로 만들거나 선택하세요</option><option v-for="w in workspaces" :key="w.id" :value="w.id">{{w.name}} · {{w.company_name}}</option></select></label>
      <form @submit.prevent="createWorkspace"><label>준비 이름<input v-model="workspace.name" required placeholder="백엔드 개발자 지원" maxlength="120"></label><div class="studio-pair"><label>기업<input v-model="workspace.company_name" required maxlength="120"></label><label>지원 직무<input v-model="workspace.target_role" required maxlength="120"></label></div><button :disabled="busy">준비자료 묶음 만들기</button></form>
      <form v-if="workspaceId" @submit.prevent="saveSource" class="studio-divider"><label>자료 종류<select v-model="source.category"><option v-for="(label,key) in categories" :key="key" :value="key">{{label}}</option></select></label><label>자료 제목<input v-model="source.title" required maxlength="200"></label><label>자료 내용<textarea v-model="source.text" required rows="5" placeholder="이력서, 포트폴리오 설명, 기업 정보 또는 채용 공고를 붙여넣으세요." /></label><button :disabled="busy">{{editingSource?'수정본 저장':'자료 저장'}}</button></form>
      <div v-if="workspaceId" class="studio-divider"><label>파일 업로드<input ref="fileInput" type="file" accept=".pdf,.docx,.txt,.md" :disabled="busy"/></label><button @click="uploadSource" :disabled="busy">선택한 종류로 파일 저장</button></div><fieldset v-if="sources.length"><legend>이번 면접에 활용할 자료</legend><label v-for="s in sources" :key="s.id" class="studio-check"><input type="checkbox" v-model="sourceIds" :value="s.id">{{categories[s.category]}} · {{s.title}}<button type="button" @click="editSource(s)" :disabled="busy">수정</button><button type="button" @click="removeSource(s)" :disabled="busy">삭제</button></label></fieldset><p v-else class="studio-muted">저장된 자료가 없습니다.</p>
    </section><section class="studio-card"><h2>02 면접 설정</h2><div class="studio-pair"><label>면접 유형<select v-model="settings.interview_type"><option value="COMPREHENSIVE">종합</option><option value="TECHNICAL">직무·기술</option><option value="BEHAVIORAL">경험·협업</option><option value="DOCUMENT_BASED">이력서·포트폴리오</option></select></label><label>난이도<select v-model="settings.difficulty"><option value="BEGINNER">초급</option><option value="INTERMEDIATE">중급</option><option value="ADVANCED">고급</option></select></label><label>면접 시간(분)<input type="number" v-model.number="settings.duration_minutes" min="5" max="60"></label><label>피드백 방식<select v-model="settings.feedback_mode"><option value="COACHING">연습 · 답변별 확인</option><option value="SIMULATION">실전 · 종료 후 확인</option></select></label></div><label>입력 방식<select v-model="settings.input_mode" :disabled="busy||recording"><option value="AUDIO_VIDEO">웹캠·마이크</option><option value="AUDIO">마이크 · 영상 미측정</option><option value="TEXT">텍스트 · 시청각 미측정</option></select></label>
      <video ref="video" autoplay muted playsinline class="studio-video" aria-label="웹캠 미리보기" /><p class="studio-muted">{{deviceMessage}}</p><button @click="checkMicrophone" :disabled="busy||!deviceReady||recording">마이크 음량·클리핑 검사</button><p class="studio-muted">{{preflightMessage}}</p><button @click="enrollSpeaker" :disabled="busy||!deviceReady||recording||settings.input_mode==='TEXT'||['ACTIVE','PAUSED','FINALIZING'].includes(session?.status)">동의하고 본인 음성 8초 등록</button><p class="studio-muted">{{enrollmentMessage}}</p><button @click="connectDevices" :disabled="busy||recording||settings.input_mode==='TEXT'">장치 확인</button><button @click="calibrateVision" :disabled="busy||!deviceReady||recording||settings.input_mode!=='AUDIO_VIDEO'">눈동자 6지점 보정</button><div v-if="calibrationTarget" ref="calibrationDialog" tabindex="-1" @keydown="calibrationKeyboard" class="gaze-calibration" role="dialog" aria-modal="true" aria-label="눈동자 시선 보정"><div class="gaze-target" :style="{left:calibrationTarget.x*100+'%',top:calibrationTarget.y*100+'%'}" aria-hidden="true">●</div><div class="gaze-controls"><p>{{calibrationIndex+1}} / 6 · {{calibrationTarget.label}}를 바라보세요.</p><p>고개를 고정하고 눈으로 지점을 바라본 뒤 수집하세요. 마지막에는 실제 카메라 렌즈를 봅니다.</p><button @click="captureCalibration" :disabled="busy">{{busy?'1.5초 관찰 중…':'이 지점 관찰 수집'}}</button><button @click="cancelCalibration" :disabled="busy">보정 취소</button><p role="alert">{{error}}</p></div></div><p class="studio-muted">{{visionMessage}} 실제 눈맞춤이나 감정·성격을 판정하지 않습니다.</p><p class="studio-muted">카메라와 마이크는 이 버튼을 눌렀을 때 연결됩니다. 분석할 수 없는 항목은 미측정으로 표시합니다.</p><button class="studio-primary" @click="start" :disabled="busy||['ACTIVE','PAUSED','FINALIZING'].includes(session?.status)||!workspaceId||settings.duration_minutes<5||settings.duration_minutes>60">면접 시작</button>
    </section></div>
  </template>
  <section v-else-if="tab==='interview'" class="studio-card"><template v-if="session"><div class="studio-heading"><h2>면접 진행</h2><strong class="studio-clock">{{clock}}</strong></div><p>상태: {{session.status}}</p><p v-if="session.timer_phase==='ANALYZING'" role="status">질문과 답변을 분석하고 있습니다. 잠시 기다려주세요.</p><h3>{{typeof session.question==='string'?session.question:session.question?.text}}</h3><video ref="video" autoplay muted playsinline class="studio-video" aria-label="면접 웹캠"/><p class="studio-muted">{{deviceMessage}}</p><button @click="checkMicrophone" :disabled="busy||!deviceReady||recording">마이크 음량·클리핑 검사</button><p class="studio-muted">{{preflightMessage}}</p><button @click="enrollSpeaker" :disabled="busy||!deviceReady||recording||settings.input_mode==='TEXT'||['ACTIVE','PAUSED','FINALIZING'].includes(session?.status)">동의하고 본인 음성 8초 등록</button><p class="studio-muted">{{enrollmentMessage}}</p><div class="studio-actions"><button @click="questionReady" :disabled="busy||recording||session.status!=='ACTIVE'||session.timer_phase==='ANALYZING'">질문 확인·답변 준비</button><span>{{questionReadyMessage}}</span><button @click="beginRecording" :disabled="busy||recording||settings.input_mode==='TEXT'||(session.status!=='ACTIVE'||session.timer_phase==='ANALYZING')">음성 녹음 시작</button><button @click="endRecording" :disabled="busy||!recording">음성 답변 종료</button><span role="status">{{recording?'녹음 중':'녹음 대기'}}</span></div><p class="studio-muted">음성 처리가 끝나면 전사를 불러와 확인하세요. 내용 평가는 확인한 답변을 사용합니다. 발음 분석을 제공할 수 없는 경우 미측정으로 표시합니다.</p><div v-if="['no_speech','no_audio','unavailable','provider_unavailable'].includes(session.transcript_status)" class="studio-error" role="status"><p>{{session.transcript_status==='no_speech'?'음성이 감지되지 않았습니다.':'음성 전사를 제공할 수 없습니다.'}} 다시 녹음하거나 텍스트로 답변하세요.</p><button @click="retryAnswer" :disabled="busy||session.status!=='ACTIVE'||remaining<=0">음성 답변 다시하기</button></div><form @submit.prevent="submitAnswer"><label>답변 확인<textarea v-model="answer" rows="7" required :disabled="busy||submissionId!==null||(session.status!=='ACTIVE'||session.timer_phase==='ANALYZING')" placeholder="답변을 작성하세요."/></label><button :disabled="busy||!answer.trim()||(session.status!=='ACTIVE'||session.timer_phase==='ANALYZING')">답변 제출</button></form><section class="studio-divider"><button @click="loadTranscripts(session.id)" :disabled="busy">음성 전사 불러오기</button><article v-for="(item,i) in transcripts" :key="i"><label>전사 확인·수정<textarea v-model="item.text" rows="4" :disabled="busy"/></label><button @click="confirmTranscript(item)" :disabled="busy||!item.text?.trim()">전사 확정 및 내용 분석</button></article></section><div class="studio-actions"><button @click="control(session.status==='PAUSED'?'resume':'pause')" :disabled="busy||!['ACTIVE','PAUSED'].includes(session.status)">{{session.status==='PAUSED'?'다시 시작':'일시정지'}}</button><button @click="finish" :disabled="busy||!['ACTIVE','PAUSED'].includes(session.status)">면접 종료 및 분석</button></div></template><p v-else>준비 화면에서 면접을 시작하세요.</p></section>
  <section v-else-if="tab==='report'" class="studio-card"><template v-if="report"><h2>나의 면접 리포트</h2><p v-if="viewingArchive">보관된 리포트 버전 {{report.revision}} · 이후 재분석과 별도로 보존된 결과입니다.</p><label>보관 리포트 버전<input type="number" min="0" v-model.number="archiveRevision" :disabled="busy"></label><button @click="openArchive" :disabled="busy||!Number.isInteger(archiveRevision)||archiveRevision<0">보관 버전 열기</button><p>음성을 다시 들으려면 전사 수정·확인을 눌러 수집 구간을 불러오세요. 보관 기간이 지난 음성은 재생할 수 없습니다.</p><button v-for="id in replayCaptureIds" :key="id" @click="replayCapture(id)" :disabled="busy">음성 구간 {{id}} 다시 듣기</button><audio v-if="replayUrl" :src="replayUrl" controls preload="metadata" aria-label="내 답변 음성 재생"/><button @click="refreshReport" :disabled="busy">분석 결과 새로고침</button><button v-if="report.session_id" @click="loadTranscripts(report.session_id)" :disabled="busy">전사 수정·확인</button><article v-for="(item,i) in transcripts" :key="i"><label>전사 확인·수정<textarea v-model="item.text" rows="4" :disabled="busy"/></label><button @click="confirmTranscript(item)" :disabled="busy||!item.text?.trim()">전사 확정 및 재분석</button></article><p>분석 상태: {{report.status}}</p><p>{{typeof report.content==='string'?report.content:report.content?.summary}}</p><div class="studio-pair"><section><h3>잘한 점</h3><p v-for="(item,i) in report.strengths" :key="i">{{item}}</p></section><section><h3>개선할 점</h3><p v-for="(item,i) in report.improvements" :key="i">{{item}}</p></section></div><article v-for="(item,index) in (Array.isArray(report.content)?report.content:[])" :key="index" class="studio-divider"><h3>{{item.question}}</h3><p style="white-space:pre-wrap">{{item.text}}</p><p>내용 분석: {{item.content_status}}</p><section v-if="item.assessment"><p>{{item.assessment.feedback}}</p><h4>잘한 점</h4><p v-for="(point,i) in item.assessment.strengths" :key="i">{{point}}</p><h4>개선할 점</h4><p v-for="(point,i) in item.assessment.improvements" :key="i">{{point}}</p></section></article><h3>관찰 및 측정</h3><div v-for="(value,key) in report.modalities" :key="key" class="studio-metric"><strong>{{metricLabels[key]||key}}</strong><div><span>{{value.status}} · {{value.reason||value.summary||''}}</span><p v-if="value.eojeol_per_minute!=null">{{formatMetric(value.eojeol_per_minute)}} 어절/분 · 측정 {{formatMetric(value.measured_seconds)}}초 · {{value.eojeol_count}}어절</p><p v-if="value.median!=null">중앙값 {{formatMetric(value.median)}} · {{value.unit}}</p><template v-if="key==='pronunciation'"><p>한국어 발음의 검증된 점수는 제공하지 않습니다. 단어별 음향 관찰은 전사·화자 구분 상태의 영향을 받습니다.</p><article v-for="turn in value.turns" :key="turn.turn_index"><strong>{{turn.turn_index+1}}번 답변 · {{turn.status}}</strong><p>{{turn.reason||turn.summary}}</p><ul><li v-for="(observation,i) in turn.observations" :key="i">{{observation.token}} · {{formatMetric(observation.start)}}–{{formatMetric(observation.end)}}초 · 음향 로그 사후확률 {{formatMetric(observation.acoustic_log_posterior)}}</li></ul></article></template><template v-if="key==='speaker_separation'"><article v-for="(analysis,i) in value.analyses" :key="i"><p>{{analysis.status}} · {{analysis.reason_code}}</p><ul><li v-for="(interval,j) in analysis.intervals" :key="j">{{formatMetric(interval.start)}}–{{formatMetric(interval.end)}}초 · {{interval.status==='candidate'?'본인 음성 추정':'화자 불확실 · 평가 제외'}}</li></ul></article></template><p v-if="value.coverage!=null">유효 관찰 {{formatMetric(value.coverage*100)}}% · {{value.valid_samples}} / {{value.total_samples}}개 표본</p></div></div></template><p v-else>완료한 면접의 리포트가 없습니다.</p></section>
  <section v-else class="studio-card"><h2>연습 기록</h2><p v-if="!history.length">아직 면접 기록이 없습니다.</p><article v-for="item in history" :key="item.id" class="studio-metric"><span>{{item.created_at}} · {{item.status}}</span><button @click="openReport(item.id)" :disabled="busy">리포트 보기</button></article></section>
</AppLayout>
</template>






